from AlgorithmImports import *


class DualStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_shares = 0
        self.aapl_shares = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {}
        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        if self.spy in data.Bars:
            spy_close = data.Bars[self.spy].Close

            if self.spy_sma.IsReady:
                self.previous_spy_close_today = spy_close
                self.previous_spy_sma_today = self.spy_sma.Current.Value
            else:
                self.previous_spy_close_today = None
                self.previous_spy_sma_today = None

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.spy in data.Bars and self.spy_sma.IsReady:
            current_spy_close = self.previous_spy_close_today
            current_spy_sma = self.previous_spy_sma_today

            if self.previous_spy_close is not None:
                prior_spy_close = self.previous_spy_close
                prior_spy_sma = self.previous_spy_sma
            else:
                prior_spy_close = None
                prior_spy_sma = None

            self.previous_spy_close = current_spy_close
            self.previous_spy_sma = current_spy_sma
        else:
            current_spy_close = None
            current_spy_sma = None
            prior_spy_close = None
            prior_spy_sma = None

        if self.IsWarmingUp:
            return

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        if (
            current_spy_close is None
            or current_spy_sma is None
            or prior_spy_close is None
            or prior_spy_sma is None
            or not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
        ):
            return

        spy_crosses_below = (
            prior_spy_close <= prior_spy_sma
            and current_spy_close < current_spy_sma
        )

        aapl_rsi_above_60 = self.aapl_rsi.Current.Value > 60

        if self.spy_shares > 0 and not self._has_pending_order("A"):
            if spy_crosses_below:
                self._submit_order("A", "sell", self.spy, -self.spy_shares)

        if self.aapl_shares > 0 and not self._has_pending_order("B"):
            if aapl_rsi_above_60:
                self._submit_order("B", "sell", self.aapl, -self.aapl_shares)

        spy_crosses_above = (
            prior_spy_close <= prior_spy_sma
            and current_spy_close > current_spy_sma
        )

        if (
            self.spy_shares == 0
            and not self._has_pending_order("A")
            and spy_crosses_above
        ):
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / current_spy_close
            )
            if quantity > 0:
                self._submit_order("A", "buy", self.spy, quantity)

        aapl_close = data.Bars[self.aapl].Close

        if (
            self.aapl_shares == 0
            and not self._has_pending_order("B")
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20000
        ):
            quantity = int(20000 / aapl_close)
            if quantity > 0:
                self._submit_order("B", "buy", self.aapl, quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        order_info = self.pending_orders.get(order_event.OrderId)
        if order_info is None:
            return

        strategy, action = order_info
        fill_quantity = int(order_event.FillQuantity)

        if strategy == "A":
            self.spy_shares += fill_quantity
            self.spy_shares = max(0, self.spy_shares)
        else:
            self.aapl_shares += fill_quantity
            self.aapl_shares = max(0, self.aapl_shares)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            del self.pending_orders[order_event.OrderId]

    def _submit_order(self, strategy, action, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        if ticket is not None:
            self.pending_orders[ticket.OrderId] = (strategy, action)

    def _has_pending_order(self, strategy):
        return any(
            order_strategy == strategy
            for order_strategy, _ in self.pending_orders.values()
        )

