from AlgorithmImports import *
import math


class TwoSlotStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(
            self.spy, 100, Resolution.Daily
        )
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending = {
            "A": False,
            "B": False
        }

        self.order_strategy = {}

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        spy_cross_above = False
        spy_cross_below = False

        if spy_bar is not None and self.spy_sma.IsReady:
            spy_close = float(spy_bar.Close)
            spy_sma_value = float(self.spy_sma.Current.Value)

            if (
                self.spy_previous_close is not None
                and self.spy_previous_sma is not None
            ):
                spy_cross_above = (
                    self.spy_previous_close <= self.spy_previous_sma
                    and spy_close > spy_sma_value
                )
                spy_cross_below = (
                    self.spy_previous_close >= self.spy_previous_sma
                    and spy_close < spy_sma_value
                )

            self.spy_previous_close = spy_close
            self.spy_previous_sma = spy_sma_value

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        if self.IsWarmingUp:
            return

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        aapl_rsi_above_60 = (
            self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60.0
        )

        sold_a = False
        sold_b = False

        if (
            self.lots["A"] > 0
            and not self.pending["A"]
            and spy_cross_below
        ):
            self._submit_order("A", self.spy, -self.lots["A"])
            sold_a = True

        if (
            self.lots["B"] > 0
            and not self.pending["B"]
            and aapl_rsi_above_60
        ):
            self._submit_order("B", self.aapl, -self.lots["B"])
            sold_b = True

        if (
            not sold_a
            and self.lots["A"] == 0
            and not self.pending["A"]
            and spy_cross_above
        ):
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            quantity = int(math.floor(target_value / float(spy_bar.Close)))

            if quantity > 0:
                self._submit_order("A", self.spy, quantity)

        if (
            not sold_b
            and self.lots["B"] == 0
            and not self.pending["B"]
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20000.0
        ):
            quantity = int(math.floor(20000.0 / float(aapl_bar.Close)))

            if quantity > 0:
                self._submit_order("B", self.aapl, quantity)

    def _submit_order(self, strategy, symbol, quantity):
        self.pending[strategy] = True
        ticket = self.MarketOrder(symbol, quantity, tag=strategy)
        self.order_strategy[ticket.OrderId] = strategy

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending[strategy] = False

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategy.get(order_event.OrderId)

        if strategy is None:
            strategy = getattr(order_event, "Tag", None)

        if strategy not in self.lots:
            return

        if order_event.FillQuantity != 0:
            self.lots[strategy] += int(order_event.FillQuantity)
            self.lots[strategy] = max(0, self.lots[strategy])

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending[strategy] = False
            self.order_strategy.pop(order_event.OrderId, None)

