from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):
    SMA_PERIOD = 200
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(
            self.spy, self.SMA_PERIOD, Resolution.Daily
        )
        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(self.SMA_PERIOD, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_buy_pending = False
        self.strategy_a_sell_pending = False
        self.strategy_b_buy_pending = False
        self.strategy_b_sell_pending = False

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        has_spy = data.Bars.ContainsKey(self.spy)
        has_aapl = data.Bars.ContainsKey(self.aapl)

        if has_aapl:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        spy_sma_ready = has_spy and self.spy_sma.IsReady
        aapl_rsi_ready = has_aapl and self.aapl_rsi.IsReady

        if (
            not self.IsWarmingUp
            and all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)
            and spy_sma_ready
            and aapl_rsi_ready
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            spy_close = float(data.Bars[self.spy].Close)
            spy_sma = float(self.spy_sma.Current.Value)
            aapl_rsi = float(self.aapl_rsi.Current.Value)

            spy_crossed_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma
            )
            spy_crossed_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_close < spy_sma
            )

            aapl_sell_reason = aapl_rsi > 60
            aapl_buy_reason = self.aapl_red_streak >= 3

            if (
                self.strategy_a_lot > 0
                and not self.strategy_a_sell_pending
                and spy_crossed_below
            ):
                self._submit_strategy_a_sell()

            if (
                self.strategy_b_lot > 0
                and not self.strategy_b_sell_pending
                and aapl_sell_reason
            ):
                self._submit_strategy_b_sell()

            if (
                self.strategy_a_lot == 0
                and not self.strategy_a_buy_pending
                and not self.strategy_a_sell_pending
                and spy_crossed_above
            ):
                target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
                quantity = int(target_value / spy_close)

                if quantity > 0:
                    self.strategy_a_buy_pending = True
                    self.MarketOrder(
                        self.spy,
                        quantity,
                        tag="Strategy A Buy"
                    )

            if (
                self.strategy_b_lot == 0
                and not self.strategy_b_buy_pending
                and not self.strategy_b_sell_pending
                and aapl_buy_reason
            ):
                available_cash = float(self.Portfolio.Cash)

                if available_cash >= 20000:
                    quantity = int(20000 / float(data.Bars[self.aapl].Close))

                    if quantity > 0:
                        self.strategy_b_buy_pending = True
                        self.MarketOrder(
                            self.aapl,
                            quantity,
                            tag="Strategy B Buy"
                        )

        if spy_sma_ready:
            self.previous_spy_close = float(data.Bars[self.spy].Close)
            self.previous_spy_sma = float(self.spy_sma.Current.Value)

    def _submit_strategy_a_sell(self):
        if self.strategy_a_lot <= 0:
            return

        self.strategy_a_sell_pending = True
        self.MarketOrder(
            self.spy,
            -self.strategy_a_lot,
            tag="Strategy A Sell"
        )

    def _submit_strategy_b_sell(self):
        if self.strategy_b_lot <= 0:
            return

        self.strategy_b_sell_pending = True
        self.MarketOrder(
            self.aapl,
            -self.strategy_b_lot,
            tag="Strategy B Sell"
        )

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        tag = order.Tag
        fill_quantity = int(order_event.FillQuantity)

        if tag == "Strategy A Buy":
            if fill_quantity > 0:
                self.strategy_a_lot += fill_quantity
        elif tag == "Strategy A Sell":
            if fill_quantity < 0:
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + fill_quantity
                )
        elif tag == "Strategy B Buy":
            if fill_quantity > 0:
                self.strategy_b_lot += fill_quantity
        elif tag == "Strategy B Sell":
            if fill_quantity < 0:
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + fill_quantity
                )
        else:
            return

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if tag == "Strategy A Buy":
                self.strategy_a_buy_pending = False
            elif tag == "Strategy A Sell":
                self.strategy_a_sell_pending = False
            elif tag == "Strategy B Buy":
