class SpyAaplStrategy(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14
    BUY_CASH_AMOUNT = 20000

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD,
            MovingAverageType.Wilders
        )

        self.SetWarmUp(self.SMA_PERIOD + 1, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}
        self.order_metadata = {}

    def OnData(self, data):
        if self.spy in data.Bars:
            spy_bar = data.Bars[self.spy]
            self.spy_sma.Update(
                IndicatorDataPoint(spy_bar.EndTime, spy_bar.Close)
            )

        if self.aapl in data.Bars:
            aapl_bar = data.Bars[self.aapl]

            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(
                IndicatorDataPoint(aapl_bar.EndTime, aapl_bar.Close)
            )
            self.previous_aapl_close = aapl_bar.Close

        spy_buy_signal = False
        spy_sell_signal = False

        if self.spy in data.Bars and self.spy_sma.IsReady:
            spy_close = data.Bars[self.spy].Close
            spy_sma_value = self.spy_sma.Current.Value

            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
            ):
                spy_buy_signal = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > spy_sma_value
                )
                spy_sell_signal = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < spy_sma_value
                )

            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma_value

        required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig,
        ]

        if self.IsWarmingUp:
            return

        if any(symbol not in data.Bars for symbol in required_symbols):
            return

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or self.previous_spy_close is None
            or self.previous_spy_sma is None
        ):
            return

        aapl_rsi_above_60 = self.aapl_rsi.Current.Value > 60

        if (
            self.strategy_a_lot > 0
            and spy_sell_signal
            and "A" not in self.pending_orders
        ):
            self._submit_order(
                "A",
                self.spy,
                -self.strategy_a_lot,
                "Strategy A sell"
            )

        if (
            self.strategy_b_lot > 0
            and aapl_rsi_above_60
            and "B" not in self.pending_orders
        ):
            self._submit_order(
                "B",
                self.aapl,
                -self.strategy_b_lot,
                "Strategy B sell"
            )

        if (
            self.strategy_a_lot == 0
            and "A" not in self.pending_orders
            and spy_buy_signal
        ):
            close = float(data.Bars[self.spy].Close)
            allocation = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(allocation / close)

            if quantity > 0:
                self._submit_order(
                    "A",
                    self.spy,
                    quantity,
                    "Strategy A buy"
                )

        if (
            self.strategy_b_lot == 0
            and "B" not in self.pending_orders
            and self.aapl_red_streak >= 3
        ):
            close = float(data.Bars[self.aapl].Close)
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= self.BUY_CASH_AMOUNT:
                quantity = int(self.BUY_CASH_AMOUNT / close)

                if quantity > 0:
                    self._submit_order(
                        "B",
                        self.aapl,
                        quantity,
                        "Strategy B buy"
                    )

    def _submit_order(self, strategy, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is not None:
            order_id = ticket.OrderId
            side = "buy" if quantity > 0 else "sell"
            self.pending_orders[strategy] = order_id
            self.order_metadata[order_id] = (strategy, side)

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.order_metadata:
            return

        strategy, side = self.order_metadata[order_id]
        fill_quantity = abs(int(order_event.FillQuantity))

        if fill_quantity > 0:
            if strategy == "A":
                if side == "buy":
                    self.strategy_a_lot += fill_quantity
                else:
                    self.strategy_a_lot = max(
                        0,
                        self.strategy_a_lot - fill_quantity
                    )
            else:
                if side == "buy":
                    self.strategy_b_lot += fill_quantity
                else:
                    self.strategy_b_lot = max(
                        0,
                        self.strategy_b_lot - fill_quantity
                    )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            if self.pending_orders.get(strategy) == order_id:
                del self.pending_orders[strategy]

            del self.order_metadata[order_id]

