                available_cash = float(self.Portfolio.Cash)
                if sold_this_bar > 0:
                    available_cash += sold_this_bar * current_aapl_close

                if available_cash >= 20000:
                    quantity = int(20000 / current_aapl_close)
                    if quantity > 0:
                        self.MarketOrder(
                            self.aapl,
                            quantity,
                            tag="Strategy B buy"
                        )
                        self.strategy_b_lot = quantity

        if current_spy_close is not None:
            self.previous_spy_close = current_spy_close
        if current_spy_sma is not None:
            self.previous_spy_sma = current_spy_sma

    def _adjust_lots_for_splits(self, data):
        if self.spy in data.Splits:
            split_factor = float(data.Splits[self.spy].SplitFactor)
